 if(w.step===1&&(!w.origin||new Date(w.availableEnd)<=new Date(w.availableStart))) throw new Error(!w.origin?'Choose a starting point from search results or enter coordinates.':'Your available evening must end after it begins.');
 if(w.step===2&&!w.interests.length) throw new Error('Pick at least one thing you’d love to see.');
