 if(!w.consent) throw new Error('Please confirm permission to save this profile.');
 const p={id:w.id,name:w.name.trim(),email:w.email.trim(),origin:w.origin,timezone:w.timezone,interests:w.interests,experience:w.experience,happyToTeach:w.experience==='experienced'&&w.happyToTeach,equipment:w.equipment,shareEquipment:w.shareEquipment,transport:w.transport,maxTravelMinutes:w.travel,maxWalkMinutes:w.walk,groupSize:{min:Math.min(w.groupMin,w.groupMax),max:w.groupMax},preference:w.preference,availability:[{start:new Date(w.availableStart).toISOString(),end:new Date(w.availableEnd).toISOString()}],...(w.transport==='drive'?{car:{available:w.carAvailable,offerRides:w.offerRides,passengerSeats:w.offerRides?w.seats:0,maxDetourMinutes:w.detour,pickupPoints:w.driverPickupPoints}}:{}),...(w.transport==='ride'?{pickup:{name:(w.pickup?w.pickupName:w.place).slice(0,120),location:w.pickup||w.origin}}:{})};
 const button=$('#wizard-form .primary');button.disabled=true;button.textContent='Saving your place…';
 try { await api('profiles',{profile:p,displayPlace:w.place,avatar:w.avatar,invitationChannel:w.invitationChannel});closeModal();await refresh();ui.view='circle';render();celebrate();toast('Your profile is saved. Welcome to the constellation.'); } finally { if(button.isConnected){button.disabled=false;button.textContent='Save my profile';} }
