function accessModal(id) {
 const p=state.outings.find(o=>o.id===id).plan;
 showModal(`<form id="access-form" data-id="${id}" class="modal-content"><div class="eyebrow">ONE LAST DETAIL, ON THE GROUND</div><h2>Make sure the spot is welcoming.</h2><p class="modal-intro">${esc(p.site.name)} is mapped as a viewpoint. Confirm it is open during this outing, and choose a safe public meeting point.</p><div class="field"><label for="access-note">How did you check night access?</label><textarea id="access-note" name="note" required minlength="10" maxlength="1000" placeholder="For example: checked the official opening hours and parking access for this date."></textarea></div><div class="row"><div class="field"><label for="meeting-lat">Meeting latitude</label><input id="meeting-lat" name="lat" type="number" step="any" min="-90" max="90" value="${p.site.meetingPoint.lat}" required></div><div class="field"><label for="meeting-lon">Meeting longitude</label><input id="meeting-lon" name="lon" type="number" step="any" min="-180" max="180" value="${p.site.meetingPoint.lon}" required></div></div><a href="https://www.google.com/maps/search/?api=1&query=${p.site.location.lat},${p.site.location.lon}" target="_blank" rel="noreferrer" style="font-size:11px">Look at the place on a map ↗</a><div class="field" style="margin-top:18px"><label for="meeting-walk">Minutes walking from meeting point to observing spot</label><input id="meeting-walk" name="walk" type="number" min="0" max="120" value="${p.site.walkMinutes}" required></div><label class="check-row"><input type="checkbox" name="confirmed" required>I have checked night access for this date and the meeting point above.</label><div id="access-error" class="form-error" role="alert"></div><button class="primary full" style="margin-top:20px" type="submit">Recheck the outing ${icon('arrow',15)}</button><p class="helper">Routes and conditions are recalculated before inviting.</p></form>`);
}
function connections() {
 const c=state.connection;
 showModal(`<div class="modal-content"><div class="eyebrow">A LITTLE HELP BEHIND THE SCENES</div><h2>Your planning companions.</h2><p class="modal-intro">The website and your agent share one local profile store. Your own Codex account handles the thinking.</p>${[['Codex agent',c.state==='ready'?'Connected through your local Codex sign-in.':c.message||'Sign in with the Codex CLI. Connection discovery can take about a minute.',c.state==='ready'],['Geoapify',c.geoapify?'Ready for live places, journeys and carpools.':'Export GEOAPIFY_API_KEY before starting the web app.',c.geoapify],['Google Calendar',c.calendar?'Connected. Invitations send only after you click Invite.':'Connect Google Calendar in Codex, then restart this web app.',c.calendar],['Your circle','A single SQLite file on this computer. No database service to run.',true]].map(([title,text,ok])=>`<div class="connection">${icon(title==='Google Calendar'?'calendar':title==='Your circle'?'people':title==='Geoapify'?'location':'spark',20)}<div><strong>${title}</strong><p>${esc(text)}</p></div><i class="dot ${ok?'good':''}"></i></div>`).join('')}<button class="text-button" data-action="reload" style="margin-top:16px">Reload connection ↻</button><div class="code">npx --no-install codex login
# Export your Geoapify key in your terminal, then:
npm run web</div>${c.state==='ready'?`<button class="secondary full" style="margin-top:20px;width:100%" data-action="agent-demo">Try a sample with my Codex agent ${icon('arrow',14)}</button><p class="helper">Uses your Codex plan · fictional data · no invitations</p>`:''}</div>`,'connections');
}
async function refresh({quiet=false}={}) {
 const next=await api('state');
 const summary=s=>[s.connection,s.jobs,s.profiles,s.outings.map(o=>[o.id,o.coordination?.status,o.coordination?.revision,o.invitation,o.plan.status,o.plan.meetingStart,o.plan.site?.name,o.coordination?.weather])];
 const changed=JSON.stringify(summary(next))!==JSON.stringify(summary(state));
 state=next;
 const job=activeJob();
 if(job?.status==='completed'&&job.result?.outingId){ui.focusOuting=job.result.outingId;ui.jobId=null;setTimeout(celebrate,120);}
 if(!quiet||changed) render();
}
async function runMatch({demo=false,agent=true}={}) {
 const {start,end}=observingWindow(ui);
 if(!demo)validateLiveWindow({start,end},ui.duration);
 if(!demo&&!organizer()){newWizard();return;}
 if(!demo&&(state.connection.state!=='ready'||!state.connection.geoapify)){connections();return;}
 const request={organizerId:ui.organizerId||state.organizerId,target:ui.target,start:start.toISOString(),end:end.toISOString(),timezone,durationMinutes:ui.duration,minPeople:ui.maxPeople===1?1:2,maxPeople:ui.maxPeople,needsGuide:ui.needsGuide};
 const job=await api('match',{mode:demo?'demo':'live',useAgent:agent,...(!demo?{request}:{})});
 ui.mode=demo?'demo':'live';ui.jobId=job.id;ui.view='explore';state.jobs.push(job);render();
}
async function action(button) {
 const a=button.dataset.action,id=button.dataset.id;
 if(a==='reload')location.reload();
 if(a==='view'){ui.view=button.dataset.view;history.replaceState(null,'',ui.view==='explore'?'/':'/?view='+ui.view);render();window.scrollTo({top:0,behavior:'smooth'});if(button.classList.contains('brand'))meteorShower();}
 if(a==='mode'){ui.mode=button.dataset.mode;ui.jobId=null;render();}
 if(a==='new-profile'){if(state.profiles.length>=8)throw new Error('Your circle already has eight profiles. Edit or remove one first.');newWizard();}
 if(a==='edit-profile')newWizard(state.profiles.find(p=>p.profile.id===id));
 if(a==='remove-profile'){
  const entry=state.profiles.find(p=>p.profile.id===id);
  showModal(`<div class="modal-content"><div class="eyebrow">YOUR CIRCLE</div><h2>Remove ${esc(entry.profile.name)}?</h2><p class="modal-intro">Their profile will no longer be used for future matching. Existing outing records and Calendar events will stay as they are.</p><button class="primary" data-action="confirm-remove" data-id="${id}">Remove profile</button> <button class="secondary" data-action="close">Keep them</button></div>`);
 }
 if(a==='confirm-remove'){await api(`profiles/${id}/delete`,{});closeModal();await refresh();toast('Profile removed from your circle.');}
 if(a==='close')closeModal();
 if(a==='target'){
  const changed=ui.target!==button.dataset.target;ui.target=button.dataset.target;render();
  if(lastClick&&changed)burst(lastClick.x,lastClick.y,{count:16,spread:.8});
  if(button.classList.contains('inspiration'))$('.planner')?.scrollIntoView({behavior:'smooth',block:'center'});
 }
 if(a==='cycle-target'){
  const i=targets.findIndex(([v])=>v===ui.target);ui.target=targets[(i+1)%targets.length][0];render();
  burstFrom($('.hero-stage'),{count:30,spread:1.2});$('.hero-stage')?.focus({preventScroll:true});
 }
 if(a==='quick-date'){
  const selection=quickDateWindow(button.dataset.date,ui),adjusted=selection.start!==ui.start;
  Object.assign(ui,selection);render();$(`[data-action="quick-date"][data-date="${ui.date}"]`)?.focus({preventScroll:true});
  if(adjusted)toast(`Start moved to ${dateLabel(`${ui.date}T${ui.start}`)}.`);
 }
 if(a==='next-fact'){factIndex=(factIndex+1)%skyFacts.length;const fact=$('.side-quote .fact');if(fact){fact.textContent=skyFacts[factIndex];fact.classList.remove('swap');void fact.offsetWidth;fact.classList.add('swap');}}
 if(a==='demo')await runMatch({demo:true,agent:false});
 if(a==='agent-demo'){closeModal();await runMatch({demo:true,agent:true});}
 if(a==='connections')connections();
 if(a==='cancel'){await api(`jobs/${id}/cancel`,{});ui.jobId=null;await refresh();toast('Search stopped.');}
 if(a==='avatar'){collectWizard();wizard.avatar=button.dataset.value;wizard.justPicked='avatar'+button.dataset.value;showWizard(`[data-action="avatar"][data-value="${button.dataset.value}"]`);}
 if(a==='wizard-choice'){
  collectWizard();const {group,value}=button.dataset;wizard.justPicked=group+value;
  if(['interests','equipment'].includes(group))wizard[group]=wizard[group].includes(value)?wizard[group].filter(v=>v!==value):[...wizard[group],value];else wizard[group]=value;
  showWizard(`[data-action="wizard-choice"][data-group="${group}"][data-value="${value}"]`);
 }
 if(a==='wizard-back'){collectWizard();wizard.step--;showWizard();}
 if(a==='lookup'){
  collectWizard();const kind=button.dataset.kind,query=kind==='origin'?wizard.place:kind==='driver-pickup'?wizard.driverPickupName:wizard.pickupName;
  if(!query.trim())throw new Error('Enter a public landmark to find.');
  button.disabled=true;button.textContent='…';
  try{
   const found=await api('geocode?q='+encodeURIComponent(query));
   const container=$(`#${kind}-results`);if(!container)return;
   container.innerHTML=found.length?`<div class="location-results">${found.map((p,i)=>`<button type="button" data-action="choose-location" data-kind="${kind}" data-index="${i}">${esc(p.name)}</button>`).join('')}</div>`:'<p class="form-error">No places found. Try a more specific landmark or city.</p>';
   wizard.locationResults=found;wizard.locationResultsKind=kind;
  }finally{if(button.isConnected){button.disabled=false;button.textContent='Find';}}
 }
 if(a==='choose-location'){
  collectWizard();const kind=button.dataset.kind;
  if(wizard.locationResultsKind!==kind)throw new Error('Find that place again before selecting it.');
  const place=wizard.locationResults[Number(button.dataset.index)];
  if(kind==='origin'){wizard.origin=place.location;wizard.place=place.name;}
  else if(kind==='driver-pickup'){
   if(wizard.driverPickupPoints.length>=3)throw new Error('You can add up to three preferred pickup points.');
   if(wizard.driverPickupPoints.some(p=>p.location.lat===place.location.lat&&p.location.lon===place.location.lon))throw new Error('That pickup point is already in your list.');
   wizard.driverPickupPoints.push({name:place.name.slice(0,120),location:place.location});wizard.driverPickupName='';
  }else{wizard.pickup=place.location;wizard.pickupName=place.name.slice(0,120);}
  showWizard();
 }
 if(a==='clear-pickup'){collectWizard();wizard.pickup=null;wizard.pickupName='';showWizard();}
 if(a==='remove-driver-pickup'){collectWizard();wizard.driverPickupPoints.splice(Number(button.dataset.index),1);showWizard();}
 if(a==='details')showDetails(id);
 if(a==='access')accessModal(id);
 if(a==='invite-preview'){button.disabled=true;try{await invitePreview(id);}finally{if(button.isConnected)button.disabled=false;}}
 if(a==='send-invite'){
  button.disabled=true;button.textContent='Checking Calendar & sending…';
  try {
   const result=await api(`outings/${id}/invite`,{token:button.dataset.token});
   await refresh();
   celebrate();showModal(`<div class="modal-content success" style="text-align:center;padding:48px 30px"><div class="success-badge">${icon('check',30)}</div><div class="eyebrow" style="justify-content:center">YOUR INVITATIONS ARE READY</div><h2>Something to look forward to.</h2><p class="modal-intro">${result.recovered?'We found the existing invitation, so no duplicate was sent.':result.channel==='local_outbox'?'Your email invitations are ready in the local outbox.':'Your invitation was created and guest notifications were requested.'} Your companions can respond on the outing page or through their Calendar invitation.</p><a class="primary" href="/outing/${id}?manage=1" target="_blank" rel="noreferrer">Open outing ${icon('arrow',15)}</a></div>`);
  }catch(error){$('#invite-error').textContent=error.message;button.textContent='Close and review before retrying';button.disabled=true;throw error;}
 }
}
document.addEventListener('click',event=>{
 const button=event.target.closest('[data-action]');if(!button||button.disabled)return;event.preventDefault();lastClick={x:event.clientX||button.getBoundingClientRect().left+button.offsetWidth/2,y:event.clientY||button.getBoundingClientRect().top+button.offsetHeight/2};
 action(button).catch(error=>{const target=$('#wizard-error')||$('#invite-error');if(target)target.textContent=error.message;else toast(error.message);});
});
document.addEventListener('input',event=>{
 const el=event.target;
 if(el.matches('#planner-form input, #planner-form select')){
  if(el.name==='organizerId'){ui.organizerId=el.value;return;}
  ui[el.name]=el.type==='checkbox'?el.checked:['duration','maxPeople'].includes(el.name)?Number(el.value):el.value;
 }
 if(el.dataset.field==='travel'){$('#travel-value').textContent=`${el.value} min · ${travelWords(Number(el.value))}`;el.style.setProperty('--fill',`${((el.value-15)/165*100).toFixed(1)}%`);}
 if(wizard&&el.dataset.field==='place') { wizard.origin=null; if($('#origin-lat'))$('#origin-lat').value=''; if($('#origin-lon'))$('#origin-lon').value=''; }
 if(wizard&&el.dataset.field==='pickupName') wizard.pickup=null;
});
document.addEventListener('submit',async event=>{
 event.preventDefault();
 try{
  if(event.target.id==='wizard-form')await saveWizard();
  if(event.target.id==='planner-form'){burstFrom(event.target.querySelector('[type=submit]'),{count:28});await runMatch({demo:ui.mode==='demo',agent:ui.mode!=='demo'});}
  if(event.target.id==='access-form'){
   const form=event.target,data=new FormData(form),button=form.querySelector('.primary');button.disabled=true;
   try{
    const job=await api(`outings/${form.dataset.id}/access`,{confirmed:data.get('confirmed')==='on',note:data.get('note'),walkMinutes:Number(data.get('walk')),meetingPoint:{lat:Number(data.get('lat')),lon:Number(data.get('lon'))}});
    closeModal();ui.jobId=job.id;ui.view='explore';state.jobs.push(job);render();
   }finally{if(button.isConnected)button.disabled=false;}
  }
 }catch(error){const target=$('#wizard-error')||$('#access-error');if(target)target.textContent=error.message;else toast(error.message);}
});
document.addEventListener('keydown',event=>{
 if(!modalType)return;
 if(event.key==='Escape'){closeModal();return;}
 if(event.key==='Tab'){
  const focusable=[...document.querySelectorAll('.modal button:not(:disabled),.modal input:not(:disabled),.modal select,.modal textarea,.modal a[href],.modal summary')].filter(el=>el.offsetParent!==null);
  const first=focusable[0],last=focusable.at(-1);
  if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}
  else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}
 }
});
initFx();
try{await refresh();pollTimer=setInterval(()=>refresh({quiet:true}).catch(()=>{clearInterval(pollTimer);state.connection={state:'error',message:'The local server restarted or disconnected. Reload this page to reconnect.'};render();}),2500);}catch(error){$('#app').innerHTML=`<div class="initial-loader"><span class="brand-star">✦</span><p>Let’s reconnect.</p><small>${esc(error.message)}</small><button class="secondary" data-action="reload">Reload Star Gazer</button></div>`;}
